        uint256 amount = 5e16; // 0.05 tokens
        uint256 allowance = 1e17; // 0.1 tokens
        uint256 ownerInitialBalance = token.balanceOf(owner);

        // Approve alice to spend owner's tokens
        vm.prank(owner);
        token.approve(alice, allowance);

        // Attempt transfer to zero address
        vm.prank(alice);
        vm.expectRevert("BEP20: transfer to the zero address");
        token.transferFrom(owner, zero, amount);

        // Verify balances unchanged
        assertEq(token.balanceOf(zero), 0, "Zero address holds tokens");
        assertEq(
            token.balanceOf(owner),
            ownerInitialBalance,
            "Owner balance changed"
        );
        assertEq(
            token.allowance(owner, alice),
            allowance,
            "Allowance changed"
        );
    }
}
